#!/usr/bin/env python3
# libxmq - Copyright (C) 2026 Fredrik Öhrström (spdx: MIT)
#
# Generate src/main/c/parts/xml_unicode.c from the libxml2 sources in 3rdparty/libxml2:
# the Unicode 4.0.1 general categories and blocks (codegen/unicode.inc, generated by
# libxml2 codegen/genUnicode.py) used by the XML Schemas regular expressions \p{..},
# \P{..}, \p{IsBlock}, \d and \w (xml_regexp.c). The tables and the xmlUCSIsCat*
# functions are copied from libxml2 with the identifiers renamed, the lookup functions
# (xmlCharInRange from chvalid.c, xmlUnicodeLookup and xmlUCSIsBlock from xmlregexp.c)
# are ported by hand below. The generated file carries the libxml2 notice.
#
# Usage: scripts/generate_xml_unicode_tables.py [libxml2_dir] [output_file]

import os
import re
import sys

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
libxml2 = sys.argv[1] if len(sys.argv) > 1 else os.path.join(root, '3rdparty', 'libxml2')
out_file = sys.argv[2] if len(sys.argv) > 2 else os.path.join(root, 'src', 'main', 'c', 'parts', 'xml_unicode.c')

inc = open(os.path.join(libxml2, 'codegen', 'unicode.inc'), encoding='utf-8').read()
copyright = open(os.path.join(libxml2, 'Copyright'), encoding='utf-8').read()
notice = copyright[copyright.index(' Copyright (C) 1998-2012'):].rstrip('\n')
version = re.search(r'LIBXML_DOTTED_VERSION "([^"]+)"',
                    open(os.path.join(libxml2, 'include', 'libxml', 'xmlversion.h'), encoding='utf-8').read()).group(1)

fixed = {
    'xmlChSRange': 'XmlUnicodeSRange',
    'xmlChLRange': 'XmlUnicodeLRange',
    'xmlChRangeGroup': 'XmlUnicodeRangeGroup',
    'xmlUnicodeRange': 'XmlUnicodeRange',
    'xmlCharInRange': 'xml_unicode_char_in_range',
    'xmlUnicodeBlocks': 'xml_unicode_blocks',
}

cats = []

def rename(m):
    name = m.group(0)
    if name in fixed:
        return fixed[name]
    c = re.match(r'xmlUCSIsCat([A-Z][a-z]?)$', name)
    if c:
        return 'xml_ucs_is_cat_' + c.group(1).lower()
    # The range tables, eg xmlLuS, xmlBasicLatinS, xmlLuG.
    return 'xml_unicode_' + name[3:]

body = re.sub(r'\bxml[A-Z][A-Za-z0-9_]*', rename, inc)
# The category functions are the api of this part.
def public(m):
    cats.append(m.group(1))
    return 'int\nxml_ucs_is_cat_' + m.group(1) + '(int code) {'
body = re.sub(r'static int\nxml_ucs_is_cat_([a-z]+)\(int code\) \{', public, body)
# Static tables of structs with const members do not need the extra const in C++.
assert 'xmlCh' not in body and 'xmlUCS' not in body
assert len(cats) == 35, cats
nblocks = len(re.findall(r'^  \{"', body, re.M))

o = []
o.append('''/* libxmq - Copyright (C) 2026 Fredrik Öhrström (spdx: MIT)

Permission is hereby granted, free of charge, to any person obtaining
a copy of this software and associated documentation files (the
"Software"), to deal in the Software without restriction, including
without limitation the rights to use, copy, modify, merge, publish,
distribute, sublicense, and/or sell copies of the Software, and to
permit persons to whom the Software is furnished to do so, subject to
the following conditions:

The above copyright notice and this permission notice shall be
included in all copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND,
EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF
MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND
NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE
LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION
OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION
WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.

*/

/* Generated by scripts/generate_xml_unicode_tables.py from libxml2 ''' + version + ''' (codegen/unicode.inc,
   chvalid.c and xmlregexp.c). Do not edit, regenerate instead.
   The tables are copied from libxml2, which is covered by the following notice
   (from libxml2/Copyright):

''' + notice + '''
*/

#ifndef BUILDING_DIST_XMQ

#include"xml_unicode.h"

#include<string.h>

#endif

#ifdef XML_UNICODE_MODULE

/* Port of xmlChSRange, xmlChLRange and xmlChRangeGroup (chvalid.h). */
typedef struct
{
    unsigned short low;
    unsigned short high;
} XmlUnicodeSRange;

typedef struct
{
    unsigned int low;
    unsigned int high;
} XmlUnicodeLRange;

typedef struct
{
    int nbShortRange;
    int nbLongRange;
    const XmlUnicodeSRange *shortRange; /* points to an array of ranges */
    const XmlUnicodeLRange *longRange;
} XmlUnicodeRangeGroup;

/* Port of xmlUnicodeRange (xmlregexp.c). */
typedef struct
{
    const char *rangename;
    const XmlUnicodeRangeGroup group;
} XmlUnicodeRange;

/**
 * Port of xmlCharInRange (chvalid.c).
 * Does a binary search of the range table to determine if char
 * is valid
 *
 * @param val  character to be validated
 * @param rptr  pointer to range to be used to validate
 * @returns true if character valid, false otherwise
 */
static int
xml_unicode_char_in_range(unsigned int val, const XmlUnicodeRangeGroup *rptr) {
    int low, high, mid;
    const XmlUnicodeSRange *sptr;
    const XmlUnicodeLRange *lptr;

    if (rptr == NULL) return(0);
    if (val < 0x10000) {	/* is val in 'short' or 'long'  array? */
	if (rptr->nbShortRange == 0)
	    return 0;
	low = 0;
	high = rptr->nbShortRange - 1;
	sptr = rptr->shortRange;
	while (low <= high) {
	    mid = (low + high) / 2;
	    if ((unsigned short) val < sptr[mid].low) {
		high = mid - 1;
	    } else {
		if ((unsigned short) val > sptr[mid].high) {
		    low = mid + 1;
		} else {
		    return 1;
		}
	    }
	}
    } else {
	if (rptr->nbLongRange == 0) {
	    return 0;
	}
	low = 0;
	high = rptr->nbLongRange - 1;
	lptr = rptr->longRange;
	while (low <= high) {
	    mid = (low + high) / 2;
	    if (val < lptr[mid].low) {
		high = mid - 1;
	    } else {
		if (val > lptr[mid].high) {
		    low = mid + 1;
		} else {
		    return 1;
		}
	    }
	}
    }
    return 0;
}

/* The tables of codegen/unicode.inc. */

''')
o.append(body.rstrip('\n') + '\n')
o.append('''
/**
 * Port of xmlUnicodeLookup (xmlregexp.c).
 * binary table lookup for user-supplied name
 *
 * @param sptr  a table of XmlUnicodeRange structs
 * @param numentries  number of table entries
 * @param tname  name to be found
 * @returns pointer to range function if found, otherwise NULL
 */
static const XmlUnicodeRangeGroup *
xml_unicode_lookup(const XmlUnicodeRange *sptr, int numentries,
                   const char *tname) {
    int low, high, mid, cmp;

    if (tname == NULL) return(NULL);

    low = 0;
    high = numentries - 1;
    while (low <= high) {
	mid = (low + high) / 2;
	cmp = strcmp(tname, sptr[mid].rangename);
	if (cmp == 0)
	    return (&sptr[mid].group);
	if (cmp < 0)
	    high = mid - 1;
	else
	    low = mid + 1;
    }
    return (NULL);
}

/**
 * Port of xmlUCSIsBlock (xmlregexp.c).
 * Check whether the character is part of the UCS Block
 *
 * @param code  UCS code point
 * @param block  UCS block name
 * @returns 1 if true, 0 if false and -1 on unknown block
 */
int
xml_ucs_is_block(int code, const char *block) {
    const XmlUnicodeRangeGroup *group;

    group = xml_unicode_lookup(xml_unicode_blocks,
            sizeof(xml_unicode_blocks) / sizeof(xml_unicode_blocks[0]), block);
    if (group == NULL)
	return (-1);
    return (xml_unicode_char_in_range(code, group));
}

#endif // XML_UNICODE_MODULE
''')
open(out_file, 'w', encoding='utf-8').write(''.join(o))
print('wrote %s: %d categories, %d blocks' % (out_file, len(cats), nblocks))
